function normaliseGuideRecitation(value) {
    return String(value || '')
        .toLowerCase()
        .replace(/[“”"'`’‘.…,()[\]]/g, ' ')
        .replace(/[-–—]/g, ' ')
        .replace(/[^a-z0-9 ]/g, '')
        .replace(/\s+/g, ' ')
        .trim();
}

function resolveGuideRecitation(entry, rawTransliteration) {
    const libraryDua = entry.duaTitle ? duas.find(dua => dua.title === entry.duaTitle) : null;
    const arabic = entry.ar || libraryDua?.ar;
    const meaning = entry.en || libraryDua?.translations?.en;
    if (!arabic || !meaning) return null;
    return {
        ar: arabic,
        tr: entry.tr || libraryDua?.tr || rawTransliteration,
        en: meaning,
        note: entry.note || ''
    };
}

function buildGuideRecitationCard(data, label = 'Recitation') {
    const card = document.createElement('span');
    card.className = 'guide-recitation';
    card.setAttribute('role', 'group');
    card.setAttribute('aria-label', `${label}: Arabic, transliteration, and meaning`);

    const arabic = document.createElement('span');
    arabic.className = 'dua-arabic';
    arabic.lang = 'ar';
    arabic.dir = 'rtl';
    arabic.textContent = data.ar;

    const transliteration = document.createElement('span');
    transliteration.className = 'dua-trans';
    const transliterationLabel = document.createElement('span');
    transliterationLabel.className = 'recitation-layer-label';
    transliterationLabel.textContent = 'Transliteration';
    transliteration.append(transliterationLabel, document.createTextNode(data.tr));

    const meaning = document.createElement('span');
    meaning.className = 'dua-eng';
    const meaningLabel = document.createElement('span');
    meaningLabel.className = 'recitation-layer-label';
    meaningLabel.textContent = 'Meaning';
    meaning.append(meaningLabel, document.createTextNode(data.en));
    if (data.note) {
        const note = document.createElement('small');
        note.className = 'guide-recitation-note';
        note.textContent = data.note;
        meaning.append(note);
    }

    card.append(arabic, transliteration, meaning);
    return card;
}

function enhanceGuideRecitations() {
    document.querySelectorAll('.guide-modal em').forEach(emphasis => {
        if (emphasis.closest('.guide-recitation')) return;
        const raw = emphasis.textContent.replace(/^["“]|["”]$/g, '').trim();
        const normalised = normaliseGuideRecitation(raw);
        const entry = GUIDE_RECITATION_LIBRARY.find(item => {
            const needle = normaliseGuideRecitation(item.needle);
            return item.exact ? normalised === needle : normalised.includes(needle);
        });
        if (!entry) return;

        const data = resolveGuideRecitation(entry, raw);
        if (!data) return;
        const parent = emphasis.parentElement;
        if (!parent) return;
        const card = buildGuideRecitationCard(data, entry.duaTitle || 'Guide recitation');

        if (entry.removeAdjacent) {
            const previous = parent.previousElementSibling;
            const next = parent.nextElementSibling;
            if (previous && /[\u0600-\u06ff]/.test(previous.textContent)) previous.remove();
            if (next && (/^\s*\(/.test(next.textContent) || next.classList.contains('dua-eng'))) next.remove();
        }

        if (entry.replaceParent && parent.tagName === 'P') parent.replaceWith(card);
        else emphasis.replaceWith(card);
    });

    document.querySelectorAll('.guide-modal .panel-content li > strong').forEach(phrase => {
        if (phrase.previousElementSibling?.classList.contains('adhan-arabic-line')) return;
        const phraseKey = normaliseGuideRecitation(phrase.textContent);
        const arabicText = ADHAN_ARABIC_PHRASES.get(phraseKey);
        if (!arabicText) return;
        const item = phrase.parentElement;
        const hasMeaning = Array.from(item?.children || []).some(child =>
            child.tagName === 'SPAN' && !child.classList.contains('adhan-arabic-line')
        );
        const arabic = document.createElement('span');
        arabic.className = 'adhan-arabic-line';
        arabic.lang = 'ar';
        arabic.dir = 'rtl';
        arabic.textContent = arabicText;
        phrase.before(arabic);
        if (!hasMeaning) {
            const englishText = ADHAN_ENGLISH_PHRASES.get(phraseKey);
            if (englishText) {
                const meaning = document.createElement('span');
                meaning.className = 'adhan-meaning-line dua-eng';
                meaning.textContent = englishText;
                phrase.after(meaning);
            }
        }
    });

    // Remove legacy "transliteration only" headings once their content has
    // been upgraded to a complete Arabic / transliteration / meaning card.
    document.querySelectorAll('.guide-modal .guide-recitation').forEach(card => {
        const wrapper = card.parentElement;
        const legacyLabel = wrapper?.querySelector(':scope > strong');
        if (!legacyLabel || !/transliteration/i.test(legacyLabel.textContent)) return;
        const lineBreak = legacyLabel.nextSibling;
        if (lineBreak?.nodeName === 'BR') lineBreak.remove();
        legacyLabel.remove();
    });
}

function classifyGuideReadingLayers() {
    document.querySelectorAll('.guide-modal strong').forEach(label => {
        const text = label.textContent.trim();
        const container = label.closest('p, div');
        if (!container || container.querySelector('.guide-recitation')) return;
        if (/transliteration/i.test(text)) container.classList.add('transliteration-layer');
        if (/^(?:the dua )?(?:translation|meaning)\s*:/i.test(text)) container.classList.add('translation-layer');
    });

    // Existing Adhan markup stores the English meaning in a direct span.
    document.querySelectorAll('.guide-modal .panel-content li > span:not(.adhan-arabic-line)').forEach(line => {
        if (line.textContent.trim() && !/[\u0600-\u06ff]/.test(line.textContent)) {
            line.classList.add('translation-layer');
        }
    });
}

