const DEEN_QUIZ_QUESTION_BANK = Object.freeze([...DEEN_QUIZ_BANK, ...DEEN_QUIZ_EXPANSION]);
const QUIZ_SURAH_NAMES = Object.freeze({
    1: 'Al-Fātiḥah', 2: 'Al-Baqarah', 3: 'Āl ʿImrān', 4: 'An-Nisāʾ', 9: 'At-Tawbah', 14: 'Ibrāhīm', 16: 'An-Naḥl', 17: 'Al-Isrāʾ', 20: 'Ṭā-Hā', 24: 'An-Nūr', 39: 'Az-Zumar', 49: 'Al-Ḥujurāt', 55: 'Ar-Raḥmān', 59: 'Al-Ḥashr', 65: 'At-Ṭalāq', 83: 'Al-Muṭaffifīn', 94: 'Ash-Sharḥ', 96: 'Al-ʿAlaq', 97: 'Al-Qadr', 103: 'Al-ʿAṣr', 110: 'An-Naṣr', 112: 'Al-Ikhlāṣ', 113: 'Al-Falaq'
});
const DEEN_QUIZ_DECK_STORAGE_KEY = 'kudu_deen_quiz_deck_v1';
let currentVerseIndex = -1;
let currentHadithIndex = -1;
let currentVerseItem = null;
let currentHadithItem = null;
let lastLiveVerseNumber = null;
let lastLiveHadithId = null;
let tasbihState = { phrase: TASBIH_PHRASES[0], counts: {} };
let currentDeenQuiz = null;
let deenQuizScore = { correct: 0, answered: 0 };
let deenQuizDeck = [];
let deenQuizLastIndex = -1;
let deenQuizRound = 0;
let deenQuizDeckHydrated = false;
let asmaQuizNameBank = null;
const REFLECTION_CACHE_KEYS = {
    verse: 'kudu_live_verse_cache',
    hadith: 'kudu_live_hadith_cache'
};

function nextReflectionIndex(items, currentIndex) {
    if (items.length < 2) return 0;
    let nextIndex;
    do nextIndex = Math.floor(Math.random() * items.length);
    while (nextIndex === currentIndex);
    return nextIndex;
}

function animateReflection(element) {
    if (!element) return;
    element.classList.remove('is-refreshing');
    void element.offsetWidth;
    element.classList.add('is-refreshing');
    setTimeout(() => element.classList.remove('is-refreshing'), 360);
}

function animateRefreshButton(buttonId) {
    const button = document.getElementById(buttonId);
    if (!button) return;
    button.classList.remove('is-spinning');
    void button.offsetWidth;
    button.classList.add('is-spinning');
    setTimeout(() => button.classList.remove('is-spinning'), 500);
}

async function fetchJsonWithTimeout(url, timeout = 9000) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);
    try {
        const response = await fetch(url, { signal: controller.signal, cache: 'no-store' });
        if (!response.ok) throw new Error(`Source returned ${response.status}`);
        return await response.json();
    } finally {
        clearTimeout(timer);
    }
}

function shuffleQuizOptions(options) {
    const shuffled = [...options];
    for (let index = shuffled.length - 1; index > 0; index--) {
        const swapIndex = Math.floor(Math.random() * (index + 1));
        [shuffled[index], shuffled[swapIndex]] = [shuffled[swapIndex], shuffled[index]];
    }
    return shuffled;
}

function restoreDeenQuizDeck() {
    if (deenQuizDeckHydrated) return;
    deenQuizDeckHydrated = true;
    try {
        const saved = JSON.parse(window.localStorage.getItem(DEEN_QUIZ_DECK_STORAGE_KEY) || 'null');
        const validDeck = Array.isArray(saved?.deck) &&
            saved?.bankSize === DEEN_QUIZ_QUESTION_BANK.length &&
            saved.deck.length <= DEEN_QUIZ_QUESTION_BANK.length &&
            new Set(saved.deck).size === saved.deck.length &&
            saved.deck.every(index => Number.isInteger(index) && index >= 0 && index < DEEN_QUIZ_QUESTION_BANK.length);
        if (!validDeck) return;
        deenQuizDeck = saved.deck;
        deenQuizLastIndex = Number.isInteger(saved.lastIndex) && saved.lastIndex >= 0 && saved.lastIndex < DEEN_QUIZ_QUESTION_BANK.length
            ? saved.lastIndex
            : -1;
        deenQuizRound = Number.isInteger(saved.round) && saved.round > 0 ? saved.round : 1;
    } catch (error) {
        // Quiz sequencing remains available when browser storage is unavailable.
    }
}

function saveDeenQuizDeck() {
    try {
        window.localStorage.setItem(DEEN_QUIZ_DECK_STORAGE_KEY, JSON.stringify({
            bankSize: DEEN_QUIZ_QUESTION_BANK.length,
            deck: deenQuizDeck,
            lastIndex: deenQuizLastIndex,
            round: deenQuizRound
        }));
    } catch (error) {
        // Quiz sequencing continues in memory when storage is unavailable.
    }
}

function getQuizSourceLabel(question) {
    const source = String(question?.source || 'Reference');
    const match = String(question?.url || '').match(/quran\.com\/(\d+)/);
    const surahName = match ? QUIZ_SURAH_NAMES[Number(match[1])] : '';
    return surahName && !source.includes(surahName) ? `${source} · ${surahName}` : source;
}

function getNextCuratedDeenQuizQuestion() {
    const bank = DEEN_QUIZ_QUESTION_BANK;
    if (!bank.length) return null;
    restoreDeenQuizDeck();
    if (!deenQuizDeck.length) {
        deenQuizRound += 1;
        deenQuizDeck = shuffleQuizOptions(bank.map((_, index) => index));
        const finalIndex = deenQuizDeck.length - 1;
        if (bank.length > 1 && deenQuizDeck[finalIndex] === deenQuizLastIndex) {
            [deenQuizDeck[0], deenQuizDeck[finalIndex]] = [deenQuizDeck[finalIndex], deenQuizDeck[0]];
        }
    }
    const index = deenQuizDeck.pop();
    deenQuizLastIndex = index;
    saveDeenQuizDeck();
    const question = bank[index];
    return {
        ...question,
        remaining: deenQuizDeck.length,
        round: deenQuizRound,
        options: shuffleQuizOptions(question.options)
    };
}

function getQuizDistractors(options, answer) {
    return shuffleQuizOptions(options.filter(option => option !== answer)).slice(0, 3);
}

async function fetchQuranQuizQuestion() {
    let lastError = null;
    for (let attempt = 0; attempt < 4; attempt++) {
        try {
            const ayahNumber = 1 + Math.floor(Math.random() * 6236);
            const payload = await fetchJsonWithTimeout(`https://api.alquran.cloud/v1/ayah/${ayahNumber}/editions/quran-uthmani,en.transliteration,en.asad`);
            const editions = Array.isArray(payload?.data) ? payload.data : [];
            const arabicEdition = editions.find(item => item?.edition?.identifier === 'quran-uthmani');
            const transliterationEdition = editions.find(item => item?.edition?.identifier === 'en.transliteration');
            const translationEdition = editions.find(item => item?.edition?.identifier === 'en.asad');
            const answer = translationEdition?.surah?.englishName;
            const arabic = typeof arabicEdition?.text === 'string' ? arabicEdition.text.trim() : '';
            const transliteration = typeof transliterationEdition?.text === 'string' ? transliterationEdition.text.trim() : '';
            const translation = typeof translationEdition?.text === 'string' ? translationEdition.text.trim() : '';
            const surah = translationEdition?.surah;
            const ayah = translationEdition?.numberInSurah;
            if (!answer || !arabic || !transliteration || !translation || !surah?.number || !ayah) throw new Error('Quiz source returned incomplete verse data');
            if (translation.length > 580 || arabic.length > 680) continue;

            return {
                kicker: 'Qur’an · identify the surah',
                prompt: 'Which surah contains this verse?',
                arabic,
                transliteration,
                translation,
                answer,
                options: shuffleQuizOptions([answer, ...getQuizDistractors(QUIZ_SURAH_OPTIONS, answer)]),
                source: `Qur’an ${surah.number}:${ayah} · Muhammad Asad translation`,
                url: `https://quran.com/${surah.number}/${ayah}`,
                live: true
            };
        } catch (error) {
            lastError = error;
        }
    }
    throw lastError || new Error('No suitable quiz verse returned');
}

async function getAsmaQuizNameBank() {
    if (Array.isArray(asmaQuizNameBank) && asmaQuizNameBank.length >= 4) return asmaQuizNameBank;
    const payload = await fetchJsonWithTimeout('https://ummahapi.com/api/asma-ul-husna');
    const names = Array.isArray(payload?.data?.names) ? payload.data.names : [];
    asmaQuizNameBank = names.filter(name =>
        typeof name?.arabic === 'string' &&
        typeof name?.transliteration === 'string' &&
        typeof name?.english === 'string' &&
        name.english.trim().length > 2
    );
    if (asmaQuizNameBank.length < 4) throw new Error('Name source returned too few choices');
    return asmaQuizNameBank;
}

async function fetchNameQuizQuestion() {
    const names = await getAsmaQuizNameBank();
    const name = shuffleQuizOptions(names)[0];
    const answer = name.english.trim();
    const arabic = name.arabic.trim();
    const transliteration = name.transliteration.trim();
    return {
        kicker: 'Asma ul Husna · the Beautiful Names',
        prompt: 'Which meaning best matches this Name of Allah?',
        arabic,
        transliteration,
        translation: 'Choose the English meaning that best matches this Name.',
        answer,
        options: shuffleQuizOptions([answer, ...getQuizDistractors(names.map(item => item.english.trim()), answer)]),
        source: 'UmmahAPI · 99 Beautiful Names of Allah',
        url: `https://ummahapi.com/api/asma-ul-husna/${name.number}`,
        live: true
    };
}

async function fetchDuaQuizQuestion() {
    const payload = await fetchJsonWithTimeout('https://ummahapi.com/api/duas/random');
    const dua = payload?.data;
    const answer = typeof dua?.category_info?.name === 'string' ? dua.category_info.name.trim() : '';
    const arabic = typeof dua?.arabic === 'string' ? dua.arabic.trim() : '';
    const transliteration = typeof dua?.transliteration === 'string' ? dua.transliteration.trim() : '';
    const translation = typeof dua?.translation === 'string' ? dua.translation.trim() : '';
    if (!answer || !arabic || !transliteration || !translation || translation.length > 260 || arabic.length > 260) throw new Error('Dua source returned unsuitable data');
    return {
        kicker: 'Dua · moments of remembrance',
        prompt: 'When is this dua commonly recited?',
        arabic,
        transliteration,
        translation,
        answer,
        options: shuffleQuizOptions([answer, ...getQuizDistractors(QUIZ_DUA_CATEGORIES, answer)]),
        source: dua.source || `UmmahAPI dua #${dua.id}`,
        url: `https://ummahapi.com/api/duas/${dua.id}`,
        live: true
    };
}

async function fetchHijriCalendarQuizQuestion() {
    const payload = await fetchJsonWithTimeout('https://ummahapi.com/api/islamic-months');
    const months = Array.isArray(payload?.data?.months) ? payload.data.months : [];
    if (months.length < 4) throw new Error('Calendar source returned too few months');
    const currentIndex = Math.floor(Math.random() * months.length);
    const current = months[currentIndex];
    const next = months[(currentIndex + 1) % months.length];
    const currentName = typeof current?.name_english === 'string' ? current.name_english.trim() : '';
    const answer = typeof next?.name_english === 'string' ? next.name_english.trim() : '';
    const arabic = typeof current?.name_arabic === 'string' ? current.name_arabic.trim() : '';
    const significance = typeof current?.significance === 'string' ? current.significance.trim() : '';
    if (!currentName || !answer || !arabic || !significance) throw new Error('Calendar source returned incomplete month data');
    return {
        kicker: 'Hijri calendar · test the sequence',
        prompt: `Which Hijri month comes after ${currentName}?`,
        arabic,
        transliteration: currentName,
        translation: significance,
        answer,
        options: shuffleQuizOptions([answer, ...getQuizDistractors(months.map(month => month.name_english), answer)]),
        source: 'UmmahAPI · Islamic months',
        url: 'https://ummahapi.com/api/islamic-months',
        live: true
    };
}

function renderQuizScore() {
    const score = document.getElementById('quiz-score');
    if (score) score.textContent = `${deenQuizScore.correct} correct · ${deenQuizScore.answered} answered`;
}

function setDeenQuizLoading(loading) {
    const button = document.getElementById('quiz-new-button');
    const status = document.getElementById('quiz-status');
    if (button) {
        button.disabled = loading;
        button.classList.toggle('is-loading', loading);
        const label = button.querySelector('span');
        if (label) label.textContent = loading ? 'Loading' : 'New';
    }
    if (status) status.textContent = loading ? 'Preparing your next learning question…' : 'Choose the best answer, then read the learning note.';
}

function renderDeenQuiz(question) {
    const prompt = document.getElementById('quiz-question');
    const verseCard = document.getElementById('quiz-verse-card');
    const verseKicker = document.getElementById('quiz-verse-kicker');
    const arabic = document.getElementById('quiz-arabic');
    const transliteration = document.getElementById('quiz-transliteration');
    const translation = document.getElementById('quiz-translation');
    const options = document.getElementById('quiz-options');
    const feedback = document.getElementById('quiz-feedback');
    const source = document.getElementById('quiz-source');
    const topic = document.getElementById('quiz-topic');
    const progress = document.getElementById('quiz-progress');
    const nextButton = document.getElementById('quiz-next-button');
    if (!prompt || !verseCard || !verseKicker || !arabic || !transliteration || !translation || !options || !feedback || !source) return;

    if (topic) topic.textContent = question.track || 'Learn & reflect';
    if (progress) {
        const freshRemaining = Number.isInteger(question.remaining) ? question.remaining : DEEN_QUIZ_QUESTION_BANK.length - 1;
        progress.textContent = freshRemaining === 0
            ? `Round ${question.round || 1} · last fresh question`
            : `Round ${question.round || 1} · ${freshRemaining} fresh left`;
    }
    prompt.textContent = question.prompt;
    verseCard.hidden = !question.arabic;
    verseKicker.textContent = question.kicker || 'Read, then answer';
    arabic.textContent = question.arabic || '';
    transliteration.textContent = question.transliteration || '';
    translation.textContent = question.translation || '';
    options.replaceChildren();
    question.options.forEach((option, index) => {
        const button = document.createElement('button');
        button.type = 'button';
        button.className = 'quiz-option';
        button.dataset.letter = String.fromCharCode(65 + index);
        button.textContent = option;
        button.addEventListener('click', () => window.answerDeenQuiz(index));
        options.appendChild(button);
    });
    feedback.classList.add('is-hidden');
    feedback.classList.remove('is-incorrect');
    if (nextButton) nextButton.hidden = true;
    const sourceLabel = getQuizSourceLabel(question);
    source.replaceChildren(document.createTextNode(`${sourceLabel} `));
    const sourceIcon = document.createElement('i');
    sourceIcon.className = 'fa-solid fa-arrow-up-right-from-square';
    sourceIcon.setAttribute('aria-hidden', 'true');
    source.append(sourceIcon);
    source.href = question.url;
    source.title = sourceLabel;
    renderQuizScore();
}

window.answerDeenQuiz = function (index) {
    if (!currentDeenQuiz) return;
    const answer = currentDeenQuiz.options[index];
    const isCorrect = answer === currentDeenQuiz.answer;
    const buttons = Array.from(document.querySelectorAll('#quiz-options .quiz-option'));
    buttons.forEach(button => {
        button.disabled = true;
        if (button.textContent === currentDeenQuiz.answer) button.classList.add('is-correct');
        else if (button.textContent === answer) button.classList.add('is-incorrect');
    });
    deenQuizScore.answered += 1;
    if (isCorrect) deenQuizScore.correct += 1;
    const feedback = document.getElementById('quiz-feedback');
    const feedbackTitle = document.getElementById('quiz-feedback-title');
    const feedbackText = document.getElementById('quiz-feedback-text');
    const feedbackIcon = feedback?.querySelector('i');
    const nextButton = document.getElementById('quiz-next-button');
    if (feedback) {
        if (feedbackTitle) feedbackTitle.textContent = isCorrect ? 'Mā shā’ Allāh — correct' : 'Learn this one';
        if (feedbackText) feedbackText.textContent = isCorrect
            ? currentDeenQuiz.explanation
            : `The best answer is “${currentDeenQuiz.answer}.” ${currentDeenQuiz.explanation}`;
        if (feedbackIcon) {
            feedbackIcon.className = isCorrect ? 'fa-solid fa-circle-check' : 'fa-solid fa-lightbulb';
            feedbackIcon.setAttribute('aria-hidden', 'true');
        }
        feedback.classList.toggle('is-incorrect', !isCorrect);
        feedback.classList.remove('is-hidden');
    }
    const status = document.getElementById('quiz-status');
    if (status) status.textContent = isCorrect ? 'Keep growing—read the note, then continue.' : 'Answer revealed—read the note, then continue.';
    if (nextButton) nextButton.hidden = false;
    currentDeenQuiz = null;
    renderQuizScore();
};

window.loadDeenQuiz = async function () {
    currentDeenQuiz = null;
    document.querySelectorAll('#quiz-options .quiz-option').forEach(button => { button.disabled = true; });
    setDeenQuizLoading(true);
    currentDeenQuiz = getNextCuratedDeenQuizQuestion();
    renderDeenQuiz(currentDeenQuiz);
    setDeenQuizLoading(false);
    animateRefreshButton('quiz-new-button');
};

function setReflectionLoading(kind, loading) {
    const button = document.getElementById(kind === 'verse' ? 'refresh-quran-button' : 'refresh-hadith-button');
    const content = document.getElementById(kind === 'verse' ? 'daily-verse-content' : 'daily-hadith-content');
    if (button) {
        button.disabled = loading;
        button.classList.toggle('is-loading', loading);
        const label = button.querySelector('span');
        if (label) label.textContent = loading ? 'Loading' : 'New';
    }
    if (content) content.setAttribute('aria-busy', String(loading));
}

function cacheLiveReflection(kind, item) {
    if (!item?.live || !REFLECTION_CACHE_KEYS[kind]) return;
    try { localStorage.setItem(REFLECTION_CACHE_KEYS[kind], JSON.stringify(item)); } catch (error) { /* Cache is optional. */ }
}

function readCachedReflection(kind) {
    try {
        const item = JSON.parse(localStorage.getItem(REFLECTION_CACHE_KEYS[kind]) || 'null');
        if (!item?.live || !item.text || !item.reference || !item.url) return null;
        if (kind === 'verse' && !item.arabic) return null;
        return { ...item, cached: true };
    } catch (error) {
        return null;
    }
}

function renderReflectionStatus(elementId, item, fallbackIndex, fallbackTotal) {
    const badge = document.getElementById(elementId);
    if (!badge) return;
    const isCached = Boolean(item?.cached);
    const isLive = Boolean(item?.live && !isCached);
    badge.classList.toggle('is-live', isLive);
    badge.classList.toggle('is-cached', isCached);
    badge.classList.toggle('is-fallback', !isLive && !isCached);
    if (isLive) {
        const fetchedAt = Number(item.fetchedAt) || Date.now();
        const time = new Date(fetchedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        badge.textContent = `Live · ${time}`;
        badge.title = 'Fetched from the live source';
    } else if (isCached) {
        const fetchedAt = Number(item.fetchedAt) || Date.now();
        const time = new Date(fetchedAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        badge.textContent = `Saved · ${time}`;
        badge.title = 'Last live item saved on this device';
    } else {
        badge.textContent = `${fallbackIndex + 1} of ${fallbackTotal}`;
        badge.title = 'Built-in offline selection';
    }
}

async function fetchLiveQuranVerse() {
    let lastError = null;
    for (let attempt = 0; attempt < 3; attempt++) {
        try {
            const ayahNumber = 1 + Math.floor(Math.random() * 6236);
            if (ayahNumber === lastLiveVerseNumber) continue;
            const payload = await fetchJsonWithTimeout(`https://api.alquran.cloud/v1/ayah/${ayahNumber}/editions/quran-uthmani,en.sahih,en.transliteration`);
            const editions = Array.isArray(payload?.data) ? payload.data : [];
            const arabic = editions.find(item => item?.edition?.identifier === 'quran-uthmani');
            const english = editions.find(item => item?.edition?.identifier === 'en.sahih');
            const transliteration = editions.find(item => item?.edition?.identifier === 'en.transliteration');
            if (!arabic?.text || !english?.text || !arabic?.surah?.number || !arabic?.numberInSurah) continue;
            lastLiveVerseNumber = ayahNumber;
            const verseKey = `${arabic.surah.number}:${arabic.numberInSurah}`;
            return {
                arabic: arabic.text,
                transliteration: transliteration?.text || '',
                text: english.text,
                reference: `Qur’an ${verseKey}`,
                url: `https://quran.com/${arabic.surah.number}/${arabic.numberInSurah}`,
                live: true,
                fetchedAt: Date.now()
            };
        } catch (error) {
            lastError = error;
        }
    }
    throw lastError || new Error('No fresh verse returned');
}

async function fetchLiveHadith() {
    let lastError = null;
    for (let attempt = 0; attempt < 4; attempt++) {
        try {
            const chapter = 1 + Math.floor(Math.random() * 97);
            const url = `https://cdn.jsdelivr.net/gh/AhmedBaset/hadith-json@v1.2.0/db/by_chapter/the_9_books/bukhari/${chapter}.json`;
            const payload = await fetchJsonWithTimeout(url);
            const hadiths = Array.isArray(payload?.hadiths) ? payload.hadiths : [];
            const suitable = hadiths.filter(item => {
                const text = item?.english?.text;
                return item?.id && item.id !== lastLiveHadithId && typeof text === 'string' && text.trim().length >= 45 && text.trim().length <= 1200;
            });
            if (!suitable.length) continue;
            const hadith = suitable[Math.floor(Math.random() * suitable.length)];
            lastLiveHadithId = hadith.id;
            const narrator = String(hadith.english.narrator || '').replace(/\s+/g, ' ').trim();
            const text = String(hadith.english.text || '').replace(/\s+/g, ' ').trim();
            return {
                text: `${narrator}${narrator ? ' ' : ''}${text}`,
                reference: `Sahih al-Bukhari ${hadith.id}`,
                url: `https://sunnah.com/bukhari:${hadith.id}`,
                live: true,
                fetchedAt: Date.now()
            };
        } catch (error) {
            lastError = error;
        }
    }
    throw lastError || new Error('No fresh Hadith returned');
}

function renderQuranVerse(animate = false) {
    const verse = currentVerseItem || DAILY_QURAN_VERSES[currentVerseIndex];
    if (!verse) return;
    document.getElementById('daily-verse-arabic').textContent = verse.arabic;
    const transliteration = document.getElementById('daily-verse-transliteration');
    transliteration.textContent = verse.transliteration || '';
    transliteration.hidden = !verse.transliteration;
    document.getElementById('daily-verse-text').textContent = verse.text;
    document.getElementById('daily-verse-reference').textContent = verse.reference;
    renderReflectionStatus('daily-verse-index', verse, currentVerseIndex, DAILY_QURAN_VERSES.length);
    document.getElementById('daily-verse-source').href = verse.url;
    if (animate) animateReflection(document.getElementById('daily-verse-content'));
}

function renderHadith(animate = false) {
    const hadith = currentHadithItem || DAILY_HADITHS[currentHadithIndex];
    if (!hadith) return;
    document.getElementById('daily-hadith-text').textContent = hadith.text;
    document.getElementById('daily-hadith-reference').textContent = hadith.reference;
    renderReflectionStatus('daily-hadith-index', hadith, currentHadithIndex, DAILY_HADITHS.length);
    document.getElementById('daily-hadith-source').href = hadith.url;
    if (animate) animateReflection(document.getElementById('daily-hadith-content'));
}

window.refreshQuranVerse = async function (silent = false) {
    setReflectionLoading('verse', true);
    try {
        currentVerseItem = await fetchLiveQuranVerse();
        cacheLiveReflection('verse', currentVerseItem);
        renderQuranVerse(true);
        animateRefreshButton('refresh-quran-button');
    } catch (error) {
        currentVerseIndex = nextReflectionIndex(DAILY_QURAN_VERSES, currentVerseIndex);
        currentVerseItem = DAILY_QURAN_VERSES[currentVerseIndex];
        renderQuranVerse(true);
        if (!silent) showToast('Live Qur’an source unavailable. Showing an offline selection.');
    } finally {
        setReflectionLoading('verse', false);
    }
};

window.refreshHadith = async function (silent = false) {
    setReflectionLoading('hadith', true);
    try {
        currentHadithItem = await fetchLiveHadith();
        cacheLiveReflection('hadith', currentHadithItem);
        renderHadith(true);
        animateRefreshButton('refresh-hadith-button');
    } catch (error) {
        currentHadithIndex = nextReflectionIndex(DAILY_HADITHS, currentHadithIndex);
        currentHadithItem = DAILY_HADITHS[currentHadithIndex];
        renderHadith(true);
        if (!silent) showToast('Live Hadith source unavailable. Showing an offline selection.');
    } finally {
        setReflectionLoading('hadith', false);
    }
};

function showReflectionCopySuccess(button, contentName) {
    if (!(button instanceof HTMLElement)) return;
    const icon = button.querySelector('i');
    const label = button.querySelector('.reflection-copy-label');
    window.clearTimeout(button._reflectionCopyTimer);
    button.classList.add('is-copied');
    button.setAttribute('aria-label', `${contentName} copied to clipboard`);
    button.title = 'Copied';
    if (icon) {
        icon.classList.remove('fa-copy', 'fa-regular');
        icon.classList.add('fa-check', 'fa-solid');
    }
    if (label) label.textContent = 'Copied';
    button._reflectionCopyTimer = window.setTimeout(() => {
        button.classList.remove('is-copied');
        button.setAttribute('aria-label', `Copy the current ${contentName}`);
        button.title = `Copy ${contentName}`;
        if (icon) {
            icon.classList.remove('fa-check', 'fa-solid');
            icon.classList.add('fa-copy', 'fa-regular');
        }
        if (label) label.textContent = 'Copy';
    }, 1800);
}

window.copyCurrentVerse = function (button) {
    const verse = currentVerseItem || DAILY_QURAN_VERSES[currentVerseIndex];
    if (!verse) return Promise.resolve(false);
    return window.copyDua(`${verse.arabic}\n\n${verse.transliteration ? `${verse.transliteration}\n\n` : ''}${verse.text}\n— ${verse.reference}\n${verse.url}`)
        .then(copied => {
            if (copied) showReflectionCopySuccess(button, "Qur'an verse");
            return copied;
        });
};

window.copyCurrentHadith = function (button) {
    const hadith = currentHadithItem || DAILY_HADITHS[currentHadithIndex];
    if (!hadith) return Promise.resolve(false);
    return window.copyDua(`${hadith.text}\n— ${hadith.reference}\n${hadith.url}`)
        .then(copied => {
            if (copied) showReflectionCopySuccess(button, 'Hadith');
            return copied;
        });
};

function saveTasbihState() {
    try { localStorage.setItem('kudu_tasbih_state', JSON.stringify(tasbihState)); } catch (error) { /* Storage may be unavailable. */ }
}

function getTasbihCount() {
    return Math.max(0, Number(tasbihState.counts[tasbihState.phrase]) || 0);
}

function renderTasbihCounter() {
    const count = getTasbihCount();
    const cycleCount = count % TASBIH_TARGET;
    const completedSets = Math.floor(count / TASBIH_TARGET);
    const displayedCycle = count > 0 && cycleCount === 0 ? TASBIH_TARGET : cycleCount;
    const progress = (displayedCycle / TASBIH_TARGET) * 100;
    document.getElementById('tasbih-count').textContent = count.toLocaleString();
    document.getElementById('tasbih-cycle').textContent = `${displayedCycle} of ${TASBIH_TARGET}`;
    document.getElementById('tasbih-sets').textContent = `${completedSets} ${completedSets === 1 ? 'set' : 'sets'} complete`;
    document.getElementById('tasbih-progress').style.width = `${progress}%`;
    const phraseDetails = TASBIH_DETAILS[tasbihState.phrase] || TASBIH_DETAILS[TASBIH_PHRASES[0]];
    document.getElementById('tasbih-phrase-arabic').textContent = phraseDetails.arabic;
    const transliteration = document.getElementById('tasbih-phrase-transliteration');
    if (transliteration) transliteration.textContent = phraseDetails.transliteration;
    const meaning = document.getElementById('tasbih-phrase-meaning');
    if (meaning) meaning.textContent = phraseDetails.meaning;
    const countButton = document.querySelector('.tasbih-count-button');
    if (countButton) {
        countButton.style.setProperty('--tasbih-progress', `${progress}%`);
        countButton.setAttribute('aria-label', `Add one ${tasbihState.phrase}. Current count ${count}`);
    }
    const undoButton = document.getElementById('tasbih-undo-button');
    if (undoButton) undoButton.disabled = count === 0;
}

window.incrementTasbih = function () {
    const nextCount = Math.min(999999, getTasbihCount() + 1);
    tasbihState.counts[tasbihState.phrase] = nextCount;
    saveTasbihState();
    renderTasbihCounter();
    if (navigator.vibrate) navigator.vibrate(8);
    if (nextCount % TASBIH_TARGET === 0) {
        const countButton = document.querySelector('.tasbih-count-button');
        countButton?.classList.remove('set-complete');
        if (countButton) void countButton.offsetWidth;
        countButton?.classList.add('set-complete');
        setTimeout(() => countButton?.classList.remove('set-complete'), 650);
        showToast(`${TASBIH_TARGET} ${tasbihState.phrase} complete.`);
    }
};

window.resetTasbihCounter = function () {
    tasbihState.counts[tasbihState.phrase] = 0;
    saveTasbihState();
    renderTasbihCounter();
    showToast(`${tasbihState.phrase} counter reset.`);
};

window.decrementTasbih = function () {
    const count = getTasbihCount();
    if (count <= 0) return;
    tasbihState.counts[tasbihState.phrase] = count - 1;
    saveTasbihState();
    renderTasbihCounter();
};

window.changeTasbihPhrase = function (phrase) {
    if (!TASBIH_PHRASES.includes(phrase)) return;
    tasbihState.phrase = phrase;
    if (!Number.isFinite(Number(tasbihState.counts[phrase]))) tasbihState.counts[phrase] = 0;
    saveTasbihState();
    renderTasbihCounter();
};

function initDailyCompanion() {
    const dayIndex = Math.floor(Date.now() / 86400000);
    currentVerseIndex = dayIndex % DAILY_QURAN_VERSES.length;
    currentHadithIndex = dayIndex % DAILY_HADITHS.length;
    currentVerseItem = readCachedReflection('verse');
    currentHadithItem = readCachedReflection('hadith');
    if (currentHadithItem) {
        const cachedHadithId = Number(String(currentHadithItem.reference).match(/(\d+)$/)?.[1]);
        if (Number.isFinite(cachedHadithId)) lastLiveHadithId = cachedHadithId;
    }
    renderQuranVerse();
    renderHadith();
    const companionDate = document.getElementById('daily-companion-date');
    if (companionDate) {
        const readableDate = new Date().toLocaleDateString('en-GB', { weekday: 'short', day: 'numeric', month: 'short' });
        companionDate.innerHTML = `<i class="fa-regular fa-calendar" aria-hidden="true"></i>${readableDate}`;
    }

    try {
        const savedState = JSON.parse(localStorage.getItem('kudu_tasbih_state') || 'null');
        if (savedState && TASBIH_PHRASES.includes(savedState.phrase) && savedState.counts && typeof savedState.counts === 'object') {
            tasbihState = { phrase: savedState.phrase, counts: savedState.counts };
        }
    } catch (error) { /* Start with a clean counter if saved data is invalid. */ }

    const phraseSelect = document.getElementById('tasbih-phrase');
    if (phraseSelect) phraseSelect.value = tasbihState.phrase;
    renderTasbihCounter();
    if (navigator.onLine !== false) {
        void window.refreshQuranVerse(true);
        void window.refreshHadith(true);
    }
}

function mountDailyCompanionPage() {
    const companionPageContent = document.getElementById('companion-page-content');
    const companionSection = document.querySelector('.daily-companion-grid');
    if (companionPageContent && companionSection && companionSection.parentElement !== companionPageContent) {
        companionPageContent.appendChild(companionSection);
    }
    companionSection?.querySelectorAll('.companion-modal').forEach(modal => document.body.appendChild(modal));
}

// === QUR’AN READER ===
