function initArabicLetterPicker() {
    const picker = document.querySelector('.arabic-letter-picker');
    if (!picker) return;
    const current = picker.querySelector('.active')?.textContent.trim() || 'ب';
    picker.replaceChildren();
    Object.keys(arabicLetterDetails).forEach(letter => {
        const button = document.createElement('button');
        const selected = letter === current;
        button.type = 'button';
        button.textContent = letter;
        button.classList.toggle('active', selected);
        button.setAttribute('aria-pressed', selected ? 'true' : 'false');
        button.setAttribute('aria-label', `Learn ${arabicLetterDetails[letter].name}`);
        button.addEventListener('click', () => window.selectArabicLetter(letter, button));
        picker.append(button);
    });
}

function readArabicNotebook() {
    try {
        const words = JSON.parse(localStorage.getItem('kudu_arabic_notebook'));
        return Array.isArray(words) ? words.filter(item => item?.arabic && item?.meaning).slice(-30) : [];
    } catch (error) { return []; }
}

function renderArabicNotebook() {
    const list = document.getElementById('arabic-notebook-list');
    if (!list) return;
    const words = readArabicNotebook();
    list.replaceChildren();
    if (!words.length) {
        const empty = document.createElement('span');
        empty.textContent = 'Save useful words here for future review.';
        list.append(empty);
        renderArabicMomentum();
        return;
    }
    words.forEach(item => {
        const word = document.createElement('span');
        const arabic = document.createElement('b');
        arabic.lang = 'ar'; arabic.dir = 'rtl'; arabic.textContent = item.arabic;
        word.append(arabic, document.createTextNode(` · ${item.meaning}`));
        list.append(word);
    });
    renderArabicMomentum();
}

window.saveArabicNotebookWord = function (arabic, meaning) {
    try {
        const words = readArabicNotebook();
        if (!words.some(item => item.arabic === arabic)) words.push({ arabic, meaning });
        localStorage.setItem('kudu_arabic_notebook', JSON.stringify(words.slice(-30)));
        renderArabicNotebook();
    } catch (error) { /* Notebook remains optional when browser storage is unavailable. */ }
};

window.clearArabicNotebook = function () {
    try { localStorage.removeItem('kudu_arabic_notebook'); } catch (error) { /* Nothing to clear when storage is unavailable. */ }
    renderArabicNotebook();
};

window.selectArabicLetter = function (letter, button) {
    const detail = arabicLetterDetails[letter];
    if (!detail) return;
    document.querySelectorAll('.arabic-letter-picker button').forEach(item => {
        const selected = item === button;
        item.classList.toggle('active', selected);
        item.setAttribute('aria-pressed', selected ? 'true' : 'false');
    });
    const symbol = document.getElementById('arabic-letter-symbol');
    const name = document.getElementById('arabic-letter-name');
    const sound = document.getElementById('arabic-letter-sound');
    const word = document.getElementById('arabic-letter-word');
    const forms = document.getElementById('arabic-letter-forms');
    if (symbol) symbol.textContent = letter;
    if (name) name.textContent = detail.name;
    if (sound) sound.textContent = detail.sound;
    if (word) {
        word.replaceChildren(document.createTextNode(`${detail.word} `));
        const transliteration = document.createElement('b');
        transliteration.textContent = detail.transliteration;
        word.append(transliteration, document.createTextNode(` · ${detail.meaning}`));
    }
    if (forms) {
        forms.replaceChildren();
        detail.forms.forEach((form, index) => {
            const formElement = document.createElement('span');
            formElement.lang = 'ar';
            formElement.textContent = form;
            forms.append(formElement);
            if (index < detail.forms.length - 1) {
                const arrow = document.createElement('i');
                arrow.className = 'fa-solid fa-arrow-left';
                arrow.setAttribute('aria-hidden', 'true');
                forms.append(arrow);
            }
        });
        forms.setAttribute('aria-label', `The available letter forms of ${detail.name}`);
    }
};

window.toggleArabicRecall = function (button) {
    const card = button?.closest('.arabic-recall-card');
    const answer = card?.querySelector('.arabic-recall-answer');
    if (!button || !answer) return;
    const revealing = answer.hidden;
    answer.hidden = !revealing;
    button.setAttribute('aria-expanded', revealing ? 'true' : 'false');
    button.innerHTML = revealing
        ? '<i class="fa-solid fa-eye-slash" aria-hidden="true"></i><span>Hide answer</span>'
        : '<i class="fa-solid fa-eye" aria-hidden="true"></i><span>Reveal answer</span>';
    const reviewActions = card?.querySelector('.arabic-review-actions');
    if (reviewActions) reviewActions.hidden = !revealing;
};

const ARABIC_REVIEW_CARDS = [
    { arabic: 'كِتَاب', answer: 'kitāb · book' },
    { arabic: 'بَيْت', answer: 'bayt · house' },
    { arabic: 'مَاء', answer: 'māʾ · water' },
    { arabic: 'طَعَام', answer: 'ṭaʿām · food' },
    { arabic: 'خَيْر', answer: 'khayr · good' }
];
let arabicReviewQueue = [];
let arabicReviewIndex = 0;
let arabicReviewKnown = 0;

function saveArabicReviewRound() {
    try {
        localStorage.setItem('kudu_arabic_review', JSON.stringify({ date: getArabicLocalDate(), completed: true, known: arabicReviewKnown }));
    } catch (error) { /* Study remains available when storage is unavailable. */ }
    renderArabicMomentum();
}

function renderArabicReview() {
    const word = document.getElementById('arabic-review-word');
    const answer = document.getElementById('arabic-review-answer');
    const reveal = document.getElementById('arabic-review-reveal');
    const actions = document.getElementById('arabic-review-actions');
    const status = document.getElementById('arabic-review-status');
    const restart = document.getElementById('arabic-review-restart');
    if (!word || !answer || !reveal || !actions || !status || !restart) return;
    const card = arabicReviewQueue[arabicReviewIndex];
    if (!card) {
        word.textContent = 'أَحْسَنْتَ';
        answer.textContent = `Round complete · ${arabicReviewKnown} of ${ARABIC_REVIEW_CARDS.length} first-pass recalls`;
        answer.hidden = false;
        reveal.hidden = true;
        actions.hidden = true;
        restart.hidden = false;
        status.textContent = 'Quick review complete. Revisit missed words tomorrow, then start another short round.';
        saveArabicReviewRound();
        return;
    }
    word.textContent = card.arabic;
    answer.textContent = card.answer;
    answer.hidden = true;
    reveal.hidden = false;
    reveal.setAttribute('aria-expanded', 'false');
    reveal.innerHTML = '<i class="fa-solid fa-eye" aria-hidden="true"></i><span>Reveal answer</span>';
    actions.hidden = true;
    restart.hidden = true;
    status.textContent = `Card ${arabicReviewIndex + 1} of ${arabicReviewQueue.length} · Say the answer aloud before revealing it.`;
}

window.startArabicReview = function () {
    arabicReviewQueue = ARABIC_REVIEW_CARDS.map(card => ({ ...card, retried: false }));
    arabicReviewIndex = 0;
    arabicReviewKnown = 0;
    renderArabicReview();
};

window.rateArabicReview = function (knewIt) {
    const card = arabicReviewQueue[arabicReviewIndex];
    if (!card) return;
    if (knewIt) arabicReviewKnown += 1;
    else if (!card.retried) arabicReviewQueue.push({ ...card, retried: true });
    arabicReviewIndex += 1;
    renderArabicReview();
};

function initArabicReview() {
    window.startArabicReview();
    initArabicMeaningQuiz();
    initArabicWritingCheck();
}

const ARABIC_MEANING_QUIZ = [
    { word: 'بَيْت', answer: 'house', options: ['house', 'book', 'water', 'day'] },
    { word: 'مَاء', answer: 'water', options: ['food', 'water', 'good', 'pen'] },
    { word: 'قَلَم', answer: 'pen', options: ['teacher', 'pen', 'mosque', 'car'] },
    { word: 'سَلَام', answer: 'peace', options: ['peace', 'sun', 'library', 'student'] }
];
const ARABIC_WRITING_CHECKS = [
    { meaning: 'water', answer: 'ماء' },
    { meaning: 'book', answer: 'كتاب' },
    { meaning: 'house', answer: 'بيت' },
    { meaning: 'pen', answer: 'قلم' }
];
let arabicQuizIndex = 0;
let arabicWritingIndex = 0;

function initArabicMeaningQuiz() {
    const question = ARABIC_MEANING_QUIZ[arabicQuizIndex];
    const word = document.getElementById('arabic-quiz-word');
    const options = document.getElementById('arabic-quiz-options');
    const status = document.getElementById('arabic-quiz-status');
    if (!question || !word || !options || !status) return;
    word.textContent = question.word;
    options.replaceChildren();
    question.options.forEach(option => {
        const button = document.createElement('button');
        button.type = 'button';
        button.textContent = option;
        button.addEventListener('click', () => window.answerArabicMeaningQuiz(option, button));
        options.append(button);
    });
    status.classList.remove('error');
    status.textContent = `Question ${arabicQuizIndex + 1} of ${ARABIC_MEANING_QUIZ.length}.`;
}

window.answerArabicMeaningQuiz = function (choice, button) {
    const question = ARABIC_MEANING_QUIZ[arabicQuizIndex];
    const options = document.getElementById('arabic-quiz-options');
    const status = document.getElementById('arabic-quiz-status');
    if (!question || !options || !status) return;
    options.querySelectorAll('button').forEach(item => item.disabled = true);
    const correct = choice === question.answer;
    button.classList.add(correct ? 'correct' : 'incorrect');
    if (!correct) Array.from(options.querySelectorAll('button')).find(item => item.textContent === question.answer)?.classList.add('correct');
    status.classList.toggle('error', !correct);
    status.textContent = correct ? 'Correct. Moving to the next word…' : `Not quite. ${question.word} means “${question.answer}.”`;
    window.setTimeout(() => { arabicQuizIndex = (arabicQuizIndex + 1) % ARABIC_MEANING_QUIZ.length; initArabicMeaningQuiz(); }, correct ? 700 : 1400);
};

function normaliseArabicForCheck(value) {
    return String(value || '').normalize('NFC').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g, '').replace(/[إأٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/\s+/g, ' ').trim();
}

function initArabicWritingCheck() {
    const item = ARABIC_WRITING_CHECKS[arabicWritingIndex];
    const meaning = document.getElementById('arabic-write-meaning');
    const input = document.getElementById('arabic-write-input');
    const status = document.getElementById('arabic-write-status');
    if (!item || !meaning || !input || !status) return;
    meaning.textContent = item.meaning;
    input.value = '';
    if (!input.dataset.enterCheck) {
        input.addEventListener('keydown', event => {
            if (event.key === 'Enter') { event.preventDefault(); window.checkArabicWriting(); }
        });
        input.dataset.enterCheck = 'true';
    }
    status.classList.remove('error');
    status.textContent = 'Use your keyboard, then compare carefully.';
}

window.checkArabicWriting = function () {
    const item = ARABIC_WRITING_CHECKS[arabicWritingIndex];
    const input = document.getElementById('arabic-write-input');
    const status = document.getElementById('arabic-write-status');
    if (!item || !input || !status) return;
    const correct = normaliseArabicForCheck(input.value) === normaliseArabicForCheck(item.answer);
    status.classList.toggle('error', !correct);
    status.textContent = correct ? `Correct: ${item.answer}. Next word coming up…` : `Try again. Hint: the answer begins with ${item.answer.charAt(0)}.`;
    if (correct) window.setTimeout(() => { arabicWritingIndex = (arabicWritingIndex + 1) % ARABIC_WRITING_CHECKS.length; initArabicWritingCheck(); }, 850);
};

window.speakArabicPractice = function (text, button) {
    const lab = button?.closest('.arabic-active-lab');
    const status = lab?.querySelector('.arabic-lab-status');
    if (!('speechSynthesis' in window)) {
        if (status) status.textContent = 'Your browser does not offer a speech voice here. Use a qualified teacher or trusted Arabic recording for pronunciation.';
        return;
    }
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'ar-SA';
    utterance.rate = .72;
    const voice = window.speechSynthesis.getVoices().find(item => item.lang?.toLowerCase().startsWith('ar'));
    if (voice) utterance.voice = voice;
    if (button) button.disabled = true;
    if (status) status.textContent = voice ? 'Playing a browser Arabic practice prompt. Compare with a qualified teacher or trusted reciter.' : 'Playing a browser voice. Arabic voice availability varies; use a qualified teacher for pronunciation.';
    utterance.onend = utterance.onerror = () => { if (button) button.disabled = false; };
    window.speechSynthesis.speak(utterance);
};

const arabicTutorPrompts = {
    gender: { title: 'Use هٰذَا with a masculine noun.', copy: 'For example: هٰذَا كِتَابٌ — this is a book. Compare it with هٰذِهِ سَيَّارَةٌ for a feminine noun. Learn the noun’s gender with the word itself.' },
    forms: { title: 'Arabic letters can change form because they connect.', copy: 'Check whether the letter joins on both sides. The six non-connectors ا د ذ ر ز و stop the connection to the following letter.' },
    root: { title: 'A root often links a family of related words.', copy: 'For example, ك ت ب connects writing-related words such as كِتَاب (book) and كَاتِب (writer). Treat roots as clues, then learn each word in context.' }
};
window.selectArabicTutorPrompt = function (prompt, button) {
    const detail = arabicTutorPrompts[prompt];
    const answer = document.getElementById('arabic-tutor-answer');
    if (!detail || !answer) return;
    document.querySelectorAll('.arabic-tutor-prompts button').forEach(item => item.classList.toggle('active', item === button));
    answer.replaceChildren();
    const title = document.createElement('strong');
    const copy = document.createElement('span');
    title.textContent = detail.title;
    copy.textContent = detail.copy;
    answer.append(title, copy);
};

let arabicSentenceWords = [];
function renderArabicSentenceBuilder() {
    const output = document.getElementById('arabic-builder-output');
    const status = document.getElementById('arabic-builder-status');
    if (output) output.textContent = arabicSentenceWords.join(' ');
    if (status && !arabicSentenceWords.length) status.textContent = 'Arabic reads right to left, but build this thought in its normal word order.';
}
window.addArabicSentenceWord = function (word) {
    if (arabicSentenceWords.length >= 2 || arabicSentenceWords.includes(word)) return;
    arabicSentenceWords.push(word);
    renderArabicSentenceBuilder();
};
window.resetArabicSentence = function () {
    arabicSentenceWords = [];
    renderArabicSentenceBuilder();
};
window.checkArabicSentence = function () {
    const status = document.getElementById('arabic-builder-status');
    if (!status) return;
    const correct = arabicSentenceWords.join(' ') === 'هٰذَا كِتَابٌ';
    status.textContent = correct ? 'Correct. هٰذَا كِتَابٌ means “This is a book.”' : 'Try again: begin with the word for “this” (masculine).';
};

const arabicContextReferences = ['1:1', '112:1', '108:1', '103:1', '94:5'];
let arabicContextIndex = 0;
window.loadArabicContext = async function () {
    const button = document.getElementById('arabic-context-load');
    const status = document.getElementById('arabic-context-status');
    const reference = document.getElementById('arabic-context-reference');
    const arabic = document.getElementById('arabic-context-arabic');
    const translation = document.getElementById('arabic-context-translation');
    if (!button || !status || !reference || !arabic || !translation) return;
    arabicContextIndex = (arabicContextIndex + 1) % arabicContextReferences.length;
    const ayahReference = arabicContextReferences[arabicContextIndex];
    button.disabled = true;
    status.textContent = 'Loading a short phrase…';
    try {
        const response = await fetch(`https://api.alquran.cloud/v1/ayah/${ayahReference}/editions/quran-uthmani,en.asad`, { headers: { Accept: 'application/json' } });
        if (!response.ok) throw new Error(`Request failed (${response.status})`);
        const payload = await response.json();
        const editions = Array.isArray(payload?.data) ? payload.data : [];
        const quranText = editions.find(item => item?.edition?.type === 'quran');
        const englishText = editions.find(item => item?.edition?.language === 'en');
        if (!quranText?.text || !englishText?.text) throw new Error('Incomplete response');
        arabic.textContent = quranText.text;
        translation.textContent = englishText.text;
        reference.textContent = `${quranText.surah?.englishName || 'Qur’an'} ${quranText.numberInSurah || ayahReference}`;
        status.textContent = 'Loaded from the public AlQuran Cloud API. Read, listen, and check meaning with trusted teachers and sources.';
    } catch (error) {
        status.textContent = 'The online source is unavailable right now. Your current phrase remains available for study; please try again when connected.';
    } finally {
        button.disabled = false;
    }
};

const ARABIC_DAILY_PROGRESS_KEY = 'kudu_arabic_daily_completion';
const ARABIC_DAILY_HISTORY_KEY = 'kudu_arabic_study_history';
function getArabicLocalDate() {
    const now = new Date();
    const offset = now.getTimezoneOffset() * 60000;
    return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}
function getArabicDateOffset(daysAgo) {
    const date = new Date();
    date.setHours(12, 0, 0, 0);
    date.setDate(date.getDate() - daysAgo);
    const offset = date.getTimezoneOffset() * 60000;
    return new Date(date.getTime() - offset).toISOString().slice(0, 10);
}
function readArabicStudyHistory() {
    try {
        const raw = localStorage.getItem(ARABIC_DAILY_HISTORY_KEY);
        const parsed = raw?.startsWith('[') ? JSON.parse(raw) : String(raw || '').split(',');
        const history = Array.isArray(parsed) ? parsed.filter(value => /^\d{4}-\d{2}-\d{2}$/.test(value)) : [];
        const legacy = localStorage.getItem(ARABIC_DAILY_PROGRESS_KEY);
        if (legacy && !history.includes(legacy)) history.push(legacy);
        return [...new Set(history)].sort().slice(-365);
    } catch (error) { return []; }
}
function renderArabicMomentum() {
    const history = readArabicStudyHistory();
    const week = document.getElementById('arabic-week-progress');
    const count = document.getElementById('arabic-streak-count');
    const title = document.getElementById('arabic-momentum-title');
    const copy = document.getElementById('arabic-momentum-copy');
    const today = getArabicLocalDate();
    let streak = 0;
    while (history.includes(getArabicDateOffset(streak))) streak += 1;
    if (week) {
        week.replaceChildren();
        for (let offset = 6; offset >= 0; offset -= 1) {
            const day = new Date(); day.setDate(day.getDate() - offset);
            const label = day.toLocaleDateString(undefined, { weekday: 'narrow' });
            const key = getArabicDateOffset(offset);
            const chip = document.createElement('span');
            chip.textContent = label;
            chip.title = key === today ? 'Today' : day.toLocaleDateString();
            chip.classList.toggle('done', history.includes(key));
            chip.classList.toggle('today', key === today);
            chip.setAttribute('aria-label', `${key}: ${history.includes(key) ? 'study complete' : 'not completed'}`);
            week.append(chip);
        }
    }
    if (count) count.textContent = String(streak);
    if (title) title.textContent = streak ? `${streak}-day study streak` : 'Start a gentle streak';
    if (copy) copy.textContent = history.includes(today) ? 'Today is complete. A short review tomorrow keeps momentum strong.' : 'Complete one focused loop a day. Short daily study compounds.';
    const sessions = document.getElementById('arabic-insight-sessions');
    const words = document.getElementById('arabic-insight-words');
    const recall = document.getElementById('arabic-insight-recall');
    if (sessions) sessions.textContent = String(history.length);
    if (words) words.textContent = String(readArabicNotebook().length);
    if (recall) {
        try {
            const latestRecall = JSON.parse(localStorage.getItem('kudu_arabic_review'));
            recall.textContent = latestRecall?.completed ? `${latestRecall.known}/5` : '—';
        } catch (error) { recall.textContent = '—'; }
    }
}
window.exportArabicLearningData = function () {
    const payload = {
        exportedAt: new Date().toISOString(),
        level: arabicSelectedLevel,
        sessionDurationMinutes: arabicSessionDuration,
        studyHistory: readArabicStudyHistory(),
        wordNotebook: readArabicNotebook(),
        latestRecall: (() => { try { return JSON.parse(localStorage.getItem('kudu_arabic_review')); } catch (error) { return null; } })()
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `kudupray-arabic-learning-${getArabicLocalDate()}.json`;
    document.body.append(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
};
function renderArabicDailyProgress() {
    const button = document.getElementById('arabic-daily-complete');
    const status = document.getElementById('arabic-daily-status');
    if (!button || !status) return;
    const completeToday = readArabicStudyHistory().includes(getArabicLocalDate());
    button.classList.toggle('completed', completeToday);
    button.setAttribute('aria-pressed', completeToday ? 'true' : 'false');
    button.innerHTML = completeToday
        ? '<i class="fa-solid fa-check" aria-hidden="true"></i><span>Completed today</span>'
        : '<i class="fa-solid fa-circle-check" aria-hidden="true"></i><span>Mark today complete</span>';
    status.textContent = completeToday
        ? 'Today’s 12-minute Arabic study loop is complete. Return tomorrow for a short review before new material.'
        : 'No study session recorded for today yet.';
    renderArabicMomentum();
}
function initArabicDailyProgress() {
    renderArabicDailyProgress();
}
window.toggleArabicDailyComplete = function () {
    try {
        const today = getArabicLocalDate();
        const history = readArabicStudyHistory();
        const completeToday = history.includes(today);
        const updated = completeToday ? history.filter(day => day !== today) : [...history, today];
        localStorage.setItem(ARABIC_DAILY_HISTORY_KEY, updated.join(','));
        if (completeToday) localStorage.removeItem(ARABIC_DAILY_PROGRESS_KEY);
        else localStorage.setItem(ARABIC_DAILY_PROGRESS_KEY, today);
        renderArabicDailyProgress();
    } catch (error) {
        const status = document.getElementById('arabic-daily-status');
        if (status) status.textContent = 'Your browser is not currently allowing progress storage. You can still follow the 12-minute study loop.';
    }
};

// --- Guides Tab Logic ---
window.openGuide = function (guideId) {
    const modal = document.getElementById('view-' + guideId);
    if (!modal) return;
    modalReturnFocus = document.activeElement;

    if (modal.hasAttribute('data-guide-page')) {
        const guidesTab = document.getElementById('tab-guides');
        document.querySelectorAll('.guide-modal[data-guide-page]').forEach(page => {
            page.classList.remove('guide-page-active');
            page.setAttribute('aria-hidden', 'true');
        });
        guidesTab?.classList.add('guide-detail-open');
        modal.classList.add('guide-page-active');
        modal.setAttribute('aria-hidden', 'false');
        document.body.classList.remove('modal-open', 'nav-hidden');
        document.body.classList.add('guide-reading-open');
        document.body.style.overflow = '';
        requestAnimationFrame(() => {
            window.scrollTo({ top: 0, behavior: 'auto' });
            modal.querySelector('.modal-body')?.scrollTo({ top: 0, behavior: 'auto' });
            modal.querySelector('.guide-back-btn')?.focus();
        });
        return;
    }

    document.querySelectorAll('body > header, body > .page, body > nav, body > .app-footer, body > #back-to-top')
        .forEach(el => {
            if (el.contains(modal)) {
                Array.from(el.children).forEach(child => {
                    if (child !== modal) {
                        child.inert = true;
                        child.dataset.modalInert = 'true';
                    }
                });
            } else {
                el.inert = true;
                el.dataset.modalInert = 'true';
            }
        });
    modal.classList.add('active');
    modal.setAttribute('aria-hidden', 'false');
    document.body.classList.remove('nav-hidden');
    document.body.classList.add('modal-open');
    document.body.style.overflow = 'hidden'; // Lock scroll
    requestAnimationFrame(() => {
        if (!modal.classList.contains('active')) return;
        modal.classList.add('is-visible');
        modal.querySelector('.modal-body')?.scrollTo({ top: 0, behavior: 'auto' });
        modal.querySelector('.modal-close-btn')?.focus();
    });
}

window.closeGuide = function () {
    const activeGuidePage = document.querySelector('.guide-modal[data-guide-page].guide-page-active');
    if (activeGuidePage) {
        activeGuidePage.classList.remove('guide-page-active');
        activeGuidePage.setAttribute('aria-hidden', 'true');
        activeGuidePage.querySelectorAll('.panel:not([hidden])').forEach(panel => {
            const button = panel.previousElementSibling;
            if (button?.classList.contains('accordion-btn')) setAccordionState(button, false);
        });
        activeGuidePage.querySelectorAll('details.info-disclosure').forEach(detail => detail.open = false);
        activeGuidePage.querySelector('.modal-body')?.scrollTo({ top: 0, behavior: 'auto' });
        document.getElementById('tab-guides')?.classList.remove('guide-detail-open');
        document.body.classList.remove('modal-open', 'nav-hidden', 'guide-reading-open');
        document.body.style.overflow = '';
        requestAnimationFrame(() => {
            window.scrollTo({ top: 0, behavior: 'auto' });
            if (modalReturnFocus instanceof HTMLElement) modalReturnFocus.focus();
            modalReturnFocus = null;
        });
        return;
    }

    const activeModals = Array.from(document.querySelectorAll('.guide-modal.active:not([data-guide-page])'));
    activeModals.forEach(el => {
        el.classList.remove('is-visible');
        el.setAttribute('aria-hidden', 'true');
    });
    const motionDuration = window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 280;
    window.setTimeout(() => {
        activeModals.forEach(el => {
            el.classList.remove('active');
            // Reset modal state after the closing transition.
            const modalBody = el.querySelector('.modal-body');
            if (modalBody) resetModal(modalBody);
            el.querySelectorAll('details.info-disclosure').forEach(detail => detail.open = false);
        });
        document.querySelectorAll('[data-modal-inert="true"]').forEach(el => {
            el.inert = false;
            delete el.dataset.modalInert;
        });
        document.body.classList.remove('modal-open', 'nav-hidden', 'guide-reading-open');
        document.body.style.overflow = ''; // Unlock scroll
        if (modalReturnFocus instanceof HTMLElement) modalReturnFocus.focus();
        modalReturnFocus = null;
    }, motionDuration);
}

function setAccordionState(btn, open) {
    const panel = btn?.nextElementSibling;
    if (!panel?.classList.contains('panel')) return;
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const duration = reduceMotion ? 0 : 360;
    const animationId = String((Number(panel.dataset.motionId || 0) + 1));
    panel.dataset.motionId = animationId;
    btn.classList.toggle('active', open);
    btn.setAttribute('aria-expanded', String(open));

    if (open) {
        panel.hidden = false;
        panel.style.overflow = 'hidden';
        panel.style.maxHeight = '0px';
        panel.style.opacity = '0';
        panel.style.transform = 'translateY(-6px)';
        requestAnimationFrame(() => {
            if (panel.dataset.motionId !== animationId) return;
            panel.style.maxHeight = `${panel.scrollHeight}px`;
            panel.style.opacity = '1';
            panel.style.transform = 'translateY(0)';
        });
        window.setTimeout(() => {
            if (panel.dataset.motionId !== animationId || !open) return;
            panel.style.maxHeight = 'none';
            panel.style.overflow = '';
        }, duration);
        return;
    }

    if (panel.hidden) return;
    panel.style.overflow = 'hidden';
    panel.style.maxHeight = `${panel.scrollHeight}px`;
    panel.style.opacity = '1';
    panel.style.transform = 'translateY(0)';
    requestAnimationFrame(() => {
        if (panel.dataset.motionId !== animationId) return;
        panel.style.maxHeight = '0px';
        panel.style.opacity = '0';
        panel.style.transform = 'translateY(-6px)';
    });
    window.setTimeout(() => {
        if (panel.dataset.motionId !== animationId || btn.getAttribute('aria-expanded') === 'true') return;
        panel.hidden = true;
        panel.style.maxHeight = '';
        panel.style.opacity = '';
        panel.style.transform = '';
        panel.style.overflow = '';
    }, duration);
}

// One open section per guide, with the selected heading held in place.
window.toggleAccordion = function (btn) {
    const panel = btn.nextElementSibling;
    if (!panel?.classList.contains('panel')) return;

    const modalBody = btn.closest('.modal-body');
    const scope = modalBody || btn.closest('.guide-modal') || document;
    const shouldOpen = btn.getAttribute('aria-expanded') !== 'true';

    scope.querySelectorAll('.accordion-btn[aria-expanded="true"]').forEach(openBtn => {
        if (openBtn !== btn) setAccordionState(openBtn, false);
    });
    setAccordionState(btn, shouldOpen);

    if (shouldOpen) alignAccordionStart(btn, modalBody);
}

function alignAccordionStart(btn, modalBody) {
    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const behavior = reduceMotion ? 'auto' : 'smooth';
    const align = () => {
        if (!btn.isConnected || btn.getAttribute('aria-expanded') !== 'true') return;
        if (modalBody) {
            const modalTop = modalBody.getBoundingClientRect().top;
            const target = Math.max(0, modalBody.scrollTop + btn.getBoundingClientRect().top - modalTop - 14);
            modalBody.scrollTo({ top: target, behavior });
            return;
        }

        const guideHeader = btn.closest('.guide-modal[data-guide-page]')?.querySelector('.modal-header-row');
        const stickyOffset = guideHeader ? Math.max(18, guideHeader.getBoundingClientRect().bottom + 12) : 88;
        const target = Math.max(0, window.scrollY + btn.getBoundingClientRect().top - stickyOffset);
        window.scrollTo({ top: target, behavior });
    };

    // Align once as the requested section starts opening, then once more after
    // the previous section's height transition has fully settled.
    requestAnimationFrame(align);
    window.setTimeout(align, reduceMotion ? 0 : 380);
}

function resetModal(modalBody) {
    modalBody.classList.remove('focused-mode');

    Array.from(modalBody.children).forEach(child => {
        if (child.classList.contains('info-disclosure')) {
            child.style.display = '';
            child.open = false;
        }
        if (child.classList.contains('visual-explainer')) {
            child.style.display = '';
        }
        if (child.classList.contains('accordion-item')) {
            child.style.display = 'block';
            // Collapse panels for clean slate
            const btn = child.querySelector('.accordion-btn');
            if (btn) {
                setAccordionState(btn, false);
            }
        }
    });
    requestAnimationFrame(() => {
        modalBody.scrollTop = 0;
    });
}

// === DUAS LOGIC ===

let activeDuaLibraryMode = 'duas';
let currentDuaPage = 1;
let showingFavouriteDuas = false;
const DUAS_PER_PAGE = 6;

function initDuaLibraryMode() {
    const modeButtons = Array.from(document.querySelectorAll('.dua-mode-button'));
    modeButtons.forEach((button, index) => {
        button.addEventListener('keydown', event => {
            if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
            event.preventDefault();
            let nextIndex = index;
            if (event.key === 'ArrowLeft') nextIndex = (index - 1 + modeButtons.length) % modeButtons.length;
            if (event.key === 'ArrowRight') nextIndex = (index + 1) % modeButtons.length;
            if (event.key === 'Home') nextIndex = 0;
            if (event.key === 'End') nextIndex = modeButtons.length - 1;
            const nextButton = modeButtons[nextIndex];
            window.setDuaLibraryMode(nextButton.dataset.duaMode, nextButton);
        });
    });
    window.setDuaLibraryMode('duas');
}

window.setDuaLibraryMode = function (mode, trigger) {
    activeDuaLibraryMode = mode === 'ruqyah' ? 'ruqyah' : 'duas';
    currentDuaPage = 1;
    const page = document.getElementById('tab-duas');
    const intro = document.getElementById('ruqyah-library-intro');
    const search = document.getElementById('search-input');
    const select = document.getElementById('dua-category-select');
    const favouritesToggle = document.getElementById('dua-favourites-toggle');
    const isRuqyah = activeDuaLibraryMode === 'ruqyah';

    page?.classList.toggle('dua-library-mode-ruqyah', isRuqyah);
    if (intro) intro.hidden = !isRuqyah;
    if (favouritesToggle) favouritesToggle.hidden = false;
    if (select) select.value = 'All';
    if (search) {
        search.value = '';
        search.placeholder = isRuqyah ? 'Search Ruqyah recitations…' : 'Search Duas…';
        search.setAttribute('aria-label', isRuqyah ? 'Search Ruqyah recitations' : 'Search duas');
    }
    document.querySelectorAll('.dua-mode-button').forEach(button => {
        const selected = button.dataset.duaMode === activeDuaLibraryMode;
        button.setAttribute('aria-selected', String(selected));
        button.tabIndex = selected ? 0 : -1;
    });
    updateSearchClearButton();
    window.filterDuaBySelect();
    if (trigger instanceof HTMLElement) trigger.focus();
};

// NEW: Unified Filter Logic (Dropdown + Search)
window.filterDuaBySelect = function (resetPage = true) {
    if (resetPage) currentDuaPage = 1;
    const select = document.getElementById('dua-category-select');
    const cat = activeDuaLibraryMode === 'ruqyah' ? 'Ruqyah' : select.value;
    syncDuaVisualCategories(cat);
    const searchVal = document.getElementById('search-input').value.toLowerCase().trim();
    const currentLang = localStorage.getItem('kudu_lang') || 'en';

    let filtered = activeDuaLibraryMode === 'ruqyah'
        ? duas.filter(d => d.cat === 'Ruqyah')
        : duas.filter(d => d.cat !== 'Ruqyah');

    // 1. Filter by Category first (if specific category selected)
    if (cat !== 'All') {
        filtered = filtered.filter(d => d.cat === cat);
    }

    // 2. Filter by Search Query
    if (searchVal) {
        filtered = filtered.filter(d => {
            // Basic Fields
            const inTitle = d.title.toLowerCase().includes(searchVal);
            const inCat = d.cat.toLowerCase().includes(searchVal);
            const inTr = d.tr.toLowerCase().includes(searchVal);
            const inAr = d.ar.includes(searchVal); // Arabic match
            const inSource = d.source ? d.source.toLowerCase().includes(searchVal) : false;

            // Translation Field (Current Language or English Fallback)
            const translation = d.translations[currentLang] || d.translations['en'];
            const inTrans = translation ? translation.toLowerCase().includes(searchVal) : false;

            return inTitle || inCat || inTr || inAr || inTrans || inSource;
        });
    }

    if (showingFavouriteDuas) {
        filtered = filtered.filter(dua => isDuaFavourite(duas.indexOf(dua)));
    }

    renderDuas(filtered);
}

// Helper to get color class based on category
function getCategoryColorClass(cat) {
    const map = {
        'Rabbana': 'chip-gold',
        'Morning': 'chip-blue',
        'Evening': 'chip-blue',
        'Nature': 'chip-blue',
        'Daily': 'chip-orange',
        'Family': 'chip-orange',
        'Social': 'chip-orange',
        'Prayer': 'chip-emerald',
        'Ruqyah': 'chip-emerald',
        'Protection': 'chip-rose',
        'Health': 'chip-rose',
        'Emotion': 'chip-rose',
        'Travel': 'chip-cyan',
        'Knowledge': 'chip-indigo',
        'Fasting': 'chip-indigo',
        'Forgiveness': 'chip-purple'
    };
    // Removed ' active' concatenation to use the pastel/bordered variant
    return (map[cat] || 'chip-emerald');
}

function getDuaFavourites() {
    try {
        const saved = JSON.parse(localStorage.getItem('kudu_dua_favourites') || '[]');
        return Array.isArray(saved) ? saved.map(Number).filter(Number.isInteger) : [];
    } catch (error) {
        return [];
    }
}

function isDuaFavourite(index) {
    return getDuaFavourites().includes(index);
}

function updateFavouriteDuaToggle() {
    const toggle = document.getElementById('dua-favourites-toggle');
    const count = document.getElementById('dua-favourites-count');
    if (!toggle || !count) return;
    const favouriteCount = getDuaFavourites().filter(index => duas[index]).length;
    toggle.classList.toggle('is-active', showingFavouriteDuas);
    toggle.querySelector('i')?.classList.toggle('fa-solid', showingFavouriteDuas);
    toggle.querySelector('i')?.classList.toggle('fa-regular', !showingFavouriteDuas);
    toggle.querySelector('span')?.replaceChildren(showingFavouriteDuas ? 'Viewing favourites' : 'Favourites');
    count.textContent = String(favouriteCount);
    toggle.setAttribute('aria-pressed', String(showingFavouriteDuas));
}

window.toggleFavouriteDuas = function () {
    showingFavouriteDuas = !showingFavouriteDuas;
    if (showingFavouriteDuas) {
        const select = document.getElementById('dua-category-select');
        const search = document.getElementById('search-input');
        if (select) select.value = 'All';
        if (search) search.value = '';
        updateSearchClearButton();
    }
    window.filterDuaBySelect();
};

function closeDuaOptions(except) {
    document.querySelectorAll('.dua-card-category-menu.is-open').forEach(menu => {
        if (menu === except) return;
        menu.classList.remove('is-open');
        menu.querySelector('.dua-options-trigger')?.setAttribute('aria-expanded', 'false');
    });
}

window.toggleDuaOptions = function (event) {
    event.stopPropagation();
    const menu = event.currentTarget.closest('.dua-card-category-menu');
    if (!menu) return;
    const willOpen = !menu.classList.contains('is-open');
    closeDuaOptions(menu);
    menu.classList.toggle('is-open', willOpen);
    event.currentTarget.setAttribute('aria-expanded', String(willOpen));
};

window.duaPillAction = function (action, index) {
    const dua = duas[index];
    if (!dua) return;
    closeDuaOptions();
    if (action === 'copy') {
        window.copyDua(dua.ar);
        return;
    }
    if (action === 'share') {
        const language = localStorage.getItem('kudu_lang') || 'en';
        const translation = dua.translations[language] || dua.translations.en;
        const text = [dua.ar, dua.tr, translation, dua.source].filter(Boolean).join('\n\n');
        if (navigator.share) {
            navigator.share({ title: 'KuduPray Dua', text }).catch(error => {
                if (error?.name !== 'AbortError') window.copyDua(text);
            });
        } else {
            window.copyDua(text);
        }
        return;
    }
    if (action === 'favourite') {
        const favourites = new Set(getDuaFavourites());
        const wasFavourite = favourites.has(index);
        if (wasFavourite) favourites.delete(index);
        else favourites.add(index);
        localStorage.setItem('kudu_dua_favourites', JSON.stringify([...favourites]));
        showToast(wasFavourite ? 'Removed from favourites.' : 'Added to favourites.');
        window.filterDuaBySelect(false);
    }
};

document.addEventListener('click', () => closeDuaOptions());

function syncDuaCategoryPicker() {
    const select = document.getElementById('dua-category-select');
    if (!select) return;
    let trigger = document.getElementById('dua-category-trigger');
    if (!trigger) {
        trigger = document.createElement('button');
        trigger.id = 'dua-category-trigger';
        trigger.type = 'button';
        trigger.setAttribute('aria-haspopup', 'listbox');
        trigger.setAttribute('aria-expanded', 'false');
        trigger.setAttribute('aria-controls', 'dua-category-list');
        select.hidden = true;
        select.after(trigger);
        const panel = document.createElement('div');
        panel.id = 'dua-category-picker';
        panel.className = 'quran-reciter-picker';
        panel.hidden = true;
        panel.innerHTML = '<div class="quran-reciter-picker-heading">Choose a category</div><div id="dua-category-list" role="listbox" aria-label="Dua categories"></div>';
        const list = panel.lastElementChild;
        const close = (restore = false) => {
            panel.hidden = true;
            trigger.setAttribute('aria-expanded', 'false');
            if (restore) trigger.focus({ preventScroll: true });
        };
        for (const item of select.options) {
            const option = document.createElement('button');
            option.type = 'button';
            option.className = 'quran-reciter-option';
            option.setAttribute('role', 'option');
            option.dataset.value = item.value;
            option.tabIndex = -1;
            const label = document.createElement('span');
            label.className = 'quran-reciter-name';
            label.textContent = item.textContent;
            const check = document.createElement('span');
            check.className = 'quran-reciter-check';
            check.textContent = '✓';
            check.setAttribute('aria-hidden', 'true');
            option.append(label, check);
            option.addEventListener('click', () => {
                select.value = item.value;
                window.filterDuaBySelect();
                syncDuaCategoryPicker();
            });
            list.append(option);
        }
        document.body.append(panel);
        const open = () => {
            panel.hidden = false;
            trigger.setAttribute('aria-expanded', 'true');
            positionQuranPicker(panel, trigger, 300);
            const selected = list.querySelector('[aria-selected="true"]');
            selected?.focus({ preventScroll: true });
            selected?.scrollIntoView({ block: 'nearest' });
        };
        trigger.addEventListener('click', () => panel.hidden ? open() : close(true));
        trigger.addEventListener('keydown', event => {
            if (['ArrowDown', 'ArrowUp'].includes(event.key)) { event.preventDefault(); open(); }
        });
        let typed = '', typedAt = 0;
        panel.addEventListener('keydown', event => {
            if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); return; }
            const options = [...list.children];
            const index = options.indexOf(document.activeElement);
            let next = -1;
            if (event.key === 'ArrowDown') next = (index + 1) % options.length;
            if (event.key === 'ArrowUp') next = (index - 1 + options.length) % options.length;
            if (event.key === 'Home') next = 0;
            if (event.key === 'End') next = options.length - 1;
            if (event.key.length === 1 && event.key !== ' ' && !event.ctrlKey && !event.metaKey && !event.altKey) {
                typed = Date.now() - typedAt > 700 ? event.key : typed + event.key;
                typedAt = Date.now();
                next = options.findIndex(option => option.textContent.toLowerCase().startsWith(typed.toLowerCase()));
            }
            if (next >= 0) { event.preventDefault(); options[next].focus({ preventScroll: true }); options[next].scrollIntoView({ block: 'nearest' }); }
        });
        document.addEventListener('pointerdown', event => { if (!panel.contains(event.target) && !trigger.contains(event.target)) close(); });
        window.addEventListener('resize', () => { if (!panel.hidden) positionQuranPicker(panel, trigger, 300); });
    }
    trigger.textContent = select.selectedOptions[0]?.textContent || 'All Categories';
    trigger.setAttribute('aria-label', `Choose a dua category: ${trigger.textContent}`);
    document.querySelectorAll('#dua-category-list [role="option"]').forEach(option => {
        option.setAttribute('aria-selected', String(option.dataset.value === select.value));
    });
}

function renderDuas(list) {
    syncDuaCategoryPicker();
    const container = document.getElementById('dua-container');
    const summary = document.getElementById('dua-result-summary');
    const pagination = document.getElementById('dua-pagination');
    const lang = localStorage.getItem('kudu_lang') || 'en';
    const category = document.getElementById('dua-category-select')?.value || 'All';
    const isRuqyah = activeDuaLibraryMode === 'ruqyah';
    updateFavouriteDuaToggle();
    if (summary) {
        if (isRuqyah) {
            summary.textContent = showingFavouriteDuas
                ? `Favourites · ${list.length}`
                : `Search Ruqyah · ${list.length}`;
        } else {
            summary.textContent = showingFavouriteDuas
                ? `Favourites · ${list.length}`
                : `Search ${category === 'All' ? 'Duas' : category} · ${list.length}`;
        }
    }

    if (list.length === 0) {
        const emptyLabel = isRuqyah ? 'No Ruqyah recitations found.' : showingFavouriteDuas ? 'No favourite duas yet.' : 'No Duas found.';
        const emptyStateType = showingFavouriteDuas ? 'is-favourites-empty' : isRuqyah ? 'is-ruqyah-empty' : '';
        const emptyIcon = showingFavouriteDuas ? 'fa-regular fa-star' : 'fa-solid fa-file-circle-xmark';
        container.innerHTML = `<div class="dua-empty-state ${emptyStateType}"><i class="${emptyIcon}" aria-hidden="true"></i><strong>${emptyLabel}</strong><span>${showingFavouriteDuas ? 'Save a dua with the star menu and it will appear here.' : 'Try another search or category.'}</span></div>`;
        if (pagination) {
            pagination.hidden = true;
            pagination.innerHTML = '';
        }
        return;
    }

    const totalPages = Math.ceil(list.length / DUAS_PER_PAGE);
    currentDuaPage = Math.min(Math.max(currentDuaPage, 1), totalPages);
    const pageStart = (currentDuaPage - 1) * DUAS_PER_PAGE;
    const pageDuas = list.slice(pageStart, pageStart + DUAS_PER_PAGE);

    container.innerHTML = pageDuas.map((d, index) => {
        const badgeClass = getCategoryColorClass(d.cat);
        const title = d.cat === 'Rabbana' ? d.title.replace(/^\d+\.\s*/, '') : d.title;
        const favourite = isDuaFavourite(duas.indexOf(d));
        // Fallback to English if translation missing
        const translation = d.translations[lang] || d.translations['en'];

        return `
            <div class="dua-card${favourite ? ' is-favourite' : ''}">
                <div class="dua-card-heading">
                    <span class="dua-number" aria-label="Dua ${pageStart + index + 1}">${pageStart + index + 1}</span>
                    <div class="dua-meta">
                        <span class="dua-title">${favourite ? '<span class="dua-favourite-mark" title="Added to favourites"><i class="fa-solid fa-star" aria-hidden="true"></i></span>' : ''}${title}</span>
                        <div class="dua-card-category-menu">
                            <button type="button" class="dua-cat ${badgeClass} dua-options-trigger" aria-label="Actions for ${title}" aria-expanded="false" onclick="toggleDuaOptions(event)">
                                <span>${d.cat}</span><i class="fa-solid fa-chevron-down" aria-hidden="true"></i>
                            </button>
                            <div class="dua-card-options" role="menu">
                                <button type="button" class="dua-card-option" role="menuitem" onclick="duaPillAction('copy', ${duas.indexOf(d)})"><i class="fa-regular fa-copy" aria-hidden="true"></i>Copy</button>
                                <button type="button" class="dua-card-option" role="menuitem" onclick="duaPillAction('share', ${duas.indexOf(d)})"><i class="fa-solid fa-share-nodes" aria-hidden="true"></i>Share</button>
                                <button type="button" class="dua-card-option" role="menuitem" onclick="duaPillAction('favourite', ${duas.indexOf(d)})"><i class="fa-${isDuaFavourite(duas.indexOf(d)) ? 'solid' : 'regular'} fa-star" aria-hidden="true"></i>${isDuaFavourite(duas.indexOf(d)) ? 'Favourited' : 'Add to favourite'}</button>
                            </div>
                        </div>
                    </div>
                </div>
                <div class="dua-arabic">${d.ar}</div>
                <div class="dua-trans">${d.tr}</div>
                <div class="dua-eng">${translation}</div>
                ${d.source ? `<div class="dua-source"><i class="fa-solid fa-book-open" aria-hidden="true"></i>${d.source}</div>` : ''}
            </div>
        `}).join('');

    if (pagination) {
        pagination.hidden = totalPages <= 1;
        pagination.innerHTML = totalPages <= 1 ? '' : `
                <button type="button" onclick="changeDuaPage(${currentDuaPage - 1})" ${currentDuaPage === 1 ? 'disabled' : ''} aria-label="Previous page"><i class="fa-solid fa-arrow-left" aria-hidden="true"></i><span>Previous</span></button>
                <span class="dua-page-status" aria-live="polite">Page ${currentDuaPage} of ${totalPages}</span>
                <button type="button" onclick="changeDuaPage(${currentDuaPage + 1})" ${currentDuaPage === totalPages ? 'disabled' : ''} aria-label="Next page"><span>Next</span><i class="fa-solid fa-arrow-right" aria-hidden="true"></i></button>`;
    }
}

window.changeDuaPage = function (page) {
    currentDuaPage = Math.max(1, Number(page) || 1);
    window.filterDuaBySelect(false);
    document.getElementById('tab-duas')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
};

// Search Listener updated to use unified filter
document.getElementById('search-input').addEventListener('input', (e) => {
    updateSearchClearButton();
    window.filterDuaBySelect();
});

function updateSearchClearButton() {
    const search = document.getElementById('search-input');
    const clear = document.getElementById('clear-search');
    if (search && clear) clear.classList.toggle('visible', Boolean(search.value.trim()));
}

function fallbackCopy(text) {
    const temp = document.createElement('textarea');
    temp.value = text;
    temp.setAttribute('readonly', '');
    temp.style.position = 'fixed';
    temp.style.left = '-9999px';
    document.body.appendChild(temp);
    temp.select();
    let copied = false;
    try { copied = document.execCommand('copy'); } catch (error) { copied = false; }
    temp.remove();
    if (copied) showToast('Copied to clipboard!');
    else showToast('Copy is unavailable in this browser.');
    return copied;
}

window.copyDua = function (text) {
    const copyText = String(text ?? '');
    if (navigator.clipboard && window.isSecureContext) {
        return navigator.clipboard.writeText(copyText)
            .then(() => {
                showToast('Copied to clipboard!');
                return true;
            })
            .catch(() => fallbackCopy(copyText));
    }
    return Promise.resolve(fallbackCopy(copyText));
}

const supportActionDrafts = Object.freeze({
    contribute: {
        to: 'support@kudupray.com',
        subject: 'Supporting KuduPray',
        message: `Assalamu alaikum,\n\nI would like to support KuduPray and help keep its worship tools free and accessible. Please let me know which kind of help would be most useful right now.\n\nI am interested in: [contributing / sharing / testing / translation / other]\n\nJazakumullahu khayran,`
    },
    review: {
        to: 'feedback@kudupray.com',
        subject: 'My KuduPray Review',
        message: `Hello KuduPray team,\n\nI would like to share an honest review.\n\nWhat I have found helpful:\n- \n\nOne thing that could be improved:\n- \n\nMay this feedback be quoted anonymously? [Yes / No]\n\nThank you,`
    },
    feedback: {
        to: 'feedback@kudupray.com',
        subject: 'KuduPray Feedback or Feature Idea',
        message: `Hello KuduPray team,\n\nI would like to share feedback.\n\nPage or feature:\n\nWhat I expected:\n\nWhat happened or what I would improve:\n\nSteps to reproduce, if relevant:\n\nDevice or browser (optional):\n\nPlease omit sensitive personal information. Thank you!`
    }
});

function setSupportActionStatus(message, trigger) {
    const status = document.getElementById('support-action-status');
    if (status) {
        const copy = status.querySelector('span');
        if (copy) copy.textContent = message;
        status.hidden = false;
    }
    if (!(trigger instanceof HTMLElement)) return;
    window.clearTimeout(trigger._supportActionTimer);
    trigger.classList.add('is-actioned');
    trigger._supportActionTimer = window.setTimeout(() => trigger.classList.remove('is-actioned'), 2200);
}

function openSupportEmail(action, trigger) {
    const draft = supportActionDrafts[action];
    if (!draft) return;
    setSupportActionStatus('Your email app is opening with a helpful template—edit anything before sending.', trigger);
    const mailto = `mailto:${draft.to}?subject=${encodeURIComponent(draft.subject)}&body=${encodeURIComponent(draft.message)}`;
    window.location.href = mailto;
}

function getKuduPrayShareData() {
    const canonicalUrl = document.querySelector('link[rel="canonical"][href]')?.href;
    const liveUrl = /^https?:$/i.test(window.location.protocol) ? window.location.href : '';
    const url = canonicalUrl || liveUrl;
    const text = 'KuduPray is a free, ad-free worship companion with prayer times, guides, and duas.';
    return { title: 'KuduPray', text, ...(url ? { url } : {}) };
}

function copySupportLink(data) {
    const copyText = data.url ? `${data.text}\n${data.url}` : data.text;
    if (navigator.clipboard && window.isSecureContext) {
        return navigator.clipboard.writeText(copyText).then(() => true).catch(() => fallbackCopy(copyText));
    }
    return Promise.resolve(fallbackCopy(copyText));
}

window.startSupportAction = function (action, trigger) {
    openSupportEmail(action, trigger);
};

window.rateApp = function (trigger) {
    openSupportEmail('review', trigger);
};

window.suggestFeature = function (trigger) {
    openSupportEmail('feedback', trigger);
};

window.shareApp = function (trigger) {
    const data = getKuduPrayShareData();
    if (navigator.share) {
        navigator.share(data)
            .then(() => setSupportActionStatus('Thank you for sharing KuduPray thoughtfully.', trigger))
            .catch(error => {
                if (error?.name === 'AbortError') {
                    setSupportActionStatus('Sharing was cancelled—nothing was sent.', trigger);
                    return;
                }
                copySupportLink(data).then(copied => {
                    setSupportActionStatus(copied ? 'A KuduPray share message was copied to your clipboard.' : 'Sharing is unavailable in this browser right now.', trigger);
                });
            });
        return;
    }
    copySupportLink(data).then(copied => {
        setSupportActionStatus(copied ? 'A KuduPray share message was copied to your clipboard.' : 'Sharing is unavailable in this browser right now.', trigger);
    });
};

window.safeOpen = function (url) {
    const opened = window.open(url, '_blank', 'noopener,noreferrer');
    if (opened) opened.opener = null;
}

function showToast(msg) {
    const toast = document.getElementById('toast');
    if (!toast) return;
    if (msg) toast.textContent = msg;
    toast.className = "show";
    setTimeout(function () {
        toast.className = toast.className.replace("show", "");
    }, 3000);
}

